'use strict';
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone = v => JSON.parse(JSON.stringify(v));
  const lines = v => String(v || '').split('\n').map(x => x.trim()).filter(Boolean);
  const slugify = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const labelStatus = s => ({draft:'Bản nháp',published:'Đã xuất bản',trash:'Thùng rác'}[s] || 'Bản nháp');
  const date = s => s ? new Date(s).toLocaleDateString('vi-VN') : '—';
  const localDateTime = s => {if(!s)return '';const d=new Date(s);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  const API = '../cms/api.php';
  const state = {user:null,csrf:'',preview:false,data:{posts:[],pages:[],categories:[],tags:[],media:[],snippets:[],settings:{},revisions:[]},section:'posts',record:null,collection:null,dirty:false,filter:'',query:'',blockIndex:0,users:[]};
  const sections = [
    ['Nội dung','posts','▤','Bài viết'],['','taxonomy','⌘','Chuyên mục & tag'],['','pages','▧','Trang & landing page'],['','media','▦','Thư viện ảnh'],
    ['Website','appearance','◫','Header & footer','admin'],['','snippets','‹›','Mã chèn','admin'],['','seo','◎','SEO & AIO'],
    ['Hệ thống','users','♙','Tài khoản quản trị','admin'],['','settings','⚙','Xuất bản & cấu hình','admin']
  ];
  const baseSettings = {id:'site',siteName:'Lazi Voyage',siteUrl:'https://lazivoyage.com',publishUrl:'https://sub.lazivoyage.com',environment:'test',header:{logo:'/assets/images/logo.webp',menu:[{label:'Trang chủ',url:'/'},{label:'Blog',url:'/blog/'},{label:'Sử Việt',url:'/su-viet/'},{label:'Liên hệ',url:'/contact/'}],sticky:true,showSearch:true},footer:{description:'Những câu chuyện du lịch, văn hóa và cuộc sống Việt Nam.',email:'lazi.voyage@gmail.com',copyright:'© Lazi Voyage',links:[]},seo:{titleTemplate:'%title% | Lazi Voyage',description:'Khám phá du lịch, văn hóa và cuộc sống Việt Nam.',organizationName:'Lazi Voyage',sameAs:[]},aio:{about:'',editorialPolicy:''}};
  function settings() { const s=state.data.settings||{};return {...baseSettings,...s,header:{...baseSettings.header,...s.header},footer:{...baseSettings.footer,...s.footer},seo:{...baseSettings.seo,...s.seo},aio:{...baseSettings.aio,...s.aio}}; }
  function notify(text, error = false) { const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,error?10000:5000); }
  async function api(action, payload, query = {}) {
    if(state.preview && payload !== undefined) throw new Error('Đang xem giao diện. Thao tác này cần CMS đã kết nối PHP và SQLite trên Vietnix.');
    const url=new URL(API,location.href);url.searchParams.set('action',action);Object.entries(query).forEach(([k,v])=>url.searchParams.set(k,v));
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),45000);
    try { const opts={credentials:'same-origin',signal:controller.signal,headers:{'Accept':'application/json'}};
      if(payload!==undefined){opts.method='POST';opts.headers['X-CSRF-Token']=state.csrf;if(payload instanceof FormData)opts.body=payload;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload);}}
      const response=await fetch(url,opts);const text=await response.text();let data;
      try{data=JSON.parse(text);}catch{throw new Error('Không nhận được phản hồi CMS. Giao diện cần PHP 8.1+ và SQLite trên Vietnix; Netlify chỉ xem được giao diện.');}
      if(!response.ok||data.error){if(response.status===401&&state.user){state.user=null;authScreen(false,'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');}throw new Error(data.error||data.message||'Không thể hoàn tất thao tác.');}
      if(data.csrf)state.csrf=data.csrf;return data.data || data;
    }catch(e){if(e.name==='AbortError')throw new Error('CMS phản hồi quá lâu. Kiểm tra kết nối trước khi thử lại.');throw e;}finally{clearTimeout(timeout);}
  }
  async function run(button, task) { if(button?.disabled)return; if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{return await task();}catch(e){notify(e.message,true);return null;}finally{if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}} }
  const button = (text,action,primary=false,extra='') => `<button type="button" class="button${primary?' primary':''}" data-action="${action}" ${extra}>${text}</button>`;
  const field = (name,label,value='',type='text',hint='') => `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}"${type==='password'?' autocomplete="new-password"':''}>${hint?`<small>${hint}</small>`:''}</label>`;
  const area = (name,label,value='',rows=3,hint='') => `<label>${label}<textarea name="${name}" rows="${rows}">${esc(value)}</textarea>${hint?`<small>${hint}</small>`:''}</label>`;
  const check = (name,label,value) => `<label class="check"><input type="checkbox" name="${name}"${value?' checked':''}>${label}</label>`;
  const inputValue = (name,form=$('#main')) => {const value=$(`[name="${name}"]`,form)?.value||'';return /password/i.test(name)?value:value.trim();};
  const checked = (name,form=$('#main')) => Boolean($(`[name="${name}"]`,form)?.checked);
  function pageHead(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">CONTENT STUDIO</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
  function openModal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
  function closeModal(){$('#modal').close();$('#modal-content').replaceChildren();}
  function authScreen(setup=false,error='',offline=false) {
    $('#auth').hidden=false;$('#app').hidden=true;
    $('#auth-content').innerHTML=offline?`<h1>CMS cần kết nối backend</h1><p class="muted">Giao diện CMS cần PHP 8.1+ và SQLite trên Vietnix; Netlify chỉ xem được giao diện.</p><div class="notice warning">${esc(error)}</div><button class="button primary" id="readonly-preview" type="button">Xem trước giao diện CMS</button><div class="auth-foot">Không có tài khoản mặc định. Sau khi cài backend, tạo quản trị viên đầu tiên bằng mã thiết lập riêng.</div>`:`<div class="eyebrow">${setup?'THIẾT LẬP BAN ĐẦU':'CHÀO MỪNG TRỞ LẠI'}</div><h1>${setup?'Tạo quản trị viên đầu tiên':'Đăng nhập Content Studio'}</h1><p class="muted">${setup?'Dùng mã thiết lập riêng do người triển khai cấp. Sau bước này, chỉ quản trị viên được tạo thêm tài khoản.':'Quản lý những câu chuyện và trải nghiệm của Lazi.'}</p><form id="auth-form" data-setup="${setup}">${error?`<div class="auth-error" role="alert">${esc(error)}</div>`:''}${setup?'<label>Mã thiết lập<input name="setupToken" type="password" autocomplete="off" required></label><label>Họ tên<input name="name" autocomplete="name" required maxlength="100"></label>':''}<label>Email<input name="email" type="email" autocomplete="username" required maxlength="254"></label><label>Mật khẩu<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" required ${setup?'minlength="12"':''}></label>${setup?'<p class="help">Mật khẩu tối thiểu 12 ký tự. Mã thiết lập không được lưu trong GitHub.</p>':''}<button class="button primary" type="submit">${setup?'Tạo tài khoản & đăng nhập':'Đăng nhập'}</button></form><div class="auth-foot">Lazi Voyage CMS · Truy cập dành cho người được cấp quyền.<br>Đăng nhập qua HTTPS khi vận hành trên Vietnix.</div>`;
    $('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;run($('button[type=submit]',form),async()=>{const payload=Object.fromEntries(new FormData(form));const result=await api(setup?'setup':'login',payload);state.user=result.user;await load();});});
    $('#readonly-preview')?.addEventListener('click',()=>startPreview());
  }
  function startPreview(){state.preview=true;state.user={id:'preview',name:'Xem giao diện',role:'admin'};state.data.settings=clone(baseSettings);$('#auth').hidden=true;$('#app').hidden=false;$('#preview-banner').hidden=false;$('#connection-status').textContent='Chỉ xem giao diện · Chưa kết nối backend';$('#logout').textContent='Đăng nhập';drawChrome();navigate('posts',true);}
  async function load(){const data=await api('bootstrap');state.data={...state.data,...data};state.user=data.user||state.user;state.dirty=false;$('#auth').hidden=true;$('#app').hidden=false;$('#preview-banner').hidden=true;drawChrome();navigate(state.section,true);}
  function drawChrome(){const s=settings();$('#workspace-name').textContent=s.siteName;try{$('#workspace-host').textContent=new URL(s.publishUrl).host;}catch{$('#workspace-host').textContent='Chưa cấu hình URL';}$('#env-label').textContent=state.preview?'XEM GIAO DIỆN':s.environment==='production'?'WEBSITE CHÍNH':'MÔI TRƯỜNG TEST';$('#account-name').textContent=state.user?.name||'Tài khoản';$('#avatar').textContent=(state.user?.name||'L').slice(0,1).toUpperCase();$('#navigation').innerHTML=sections.filter(s=>!s[4]||state.user?.role==='admin').map(([group,key,icon,name])=>`${group?`<div class="nav-group">${group}</div>`:''}<button type="button" class="nav-button" data-section="${key}"${key===state.section?' aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</button>`).join('');}
  function navigate(section,force=false){if(state.dirty&&!force&&!confirm('Bạn đang có thay đổi chưa lưu. Rời màn hình này?'))return;if(!sections.some(s=>s[1]===section))section='posts';state.section=section;state.record=null;state.collection=null;state.dirty=false;state.filter='';state.query='';drawChrome();$('#breadcrumb-title').textContent=sections.find(s=>s[1]===section)[3];$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');render();}
  function render(){({posts:()=>renderList('posts'),pages:()=>renderList('pages'),taxonomy:renderTaxonomy,media:renderMedia,appearance:renderAppearance,snippets:renderSnippets,seo:renderSEO,users:renderUsers,settings:renderSettings}[state.section]||(()=>renderList('posts')))();}
  function renderList(collection){const isPage=collection==='pages';const all=state.data[collection]||[];const items=all.filter(r=>(!state.query||`${r.title} ${r.slug}`.toLowerCase().includes(state.query.toLowerCase()))&&(!state.filter||r.status===state.filter));const main=$('#main');main.innerHTML=pageHead(isPage?'Trang & landing page':'Những câu chuyện của Lazi',isPage?'Tạo các trang giới thiệu, nội dung cố định và landing page từ những khối có sẵn.':'Viết, biên tập và xuất bản nội dung. Bản nháp được giữ riêng với nội dung đang hiển thị.',button(isPage?'+ Tạo trang':'+ Viết bài mới','new-record',true,`data-collection="${collection}"`))+`<div class="summary-strip"><div class="summary-item"><strong>${all.length}</strong><span>Tổng ${isPage?'số trang':'bài viết'}</span></div><div class="summary-item"><strong>${all.filter(r=>r.status==='published').length}</strong><span>Đã xuất bản</span></div><div class="summary-item"><strong>${all.filter(r=>r.status==='draft').length}</strong><span>Bản nháp</span></div></div><div class="filters"><input id="list-search" aria-label="Tìm nội dung" placeholder="Tìm theo tiêu đề hoặc đường dẫn…" value="${esc(state.query)}"><select id="list-status" aria-label="Lọc trạng thái"><option value="">Mọi trạng thái</option>${['draft','published','trash'].map(s=>`<option value="${s}"${s===state.filter?' selected':''}>${labelStatus(s)}</option>`).join('')}</select></div><div class="list-surface">${items.length?`<div class="table-wrap"><table><thead><tr><th>${isPage?'Trang':'Bài viết'}</th><th class="hide-mobile">${isPage?'Loại trang':'Chuyên mục'}</th><th>Trạng thái</th><th class="hide-mobile">Cập nhật</th><th></th></tr></thead><tbody>${items.map(r=>`<tr><td><button type="button" class="title-button" data-action="edit-record" data-collection="${collection}" data-id="${esc(r.id)}">${esc(r.title||'Chưa có tiêu đề')}</button><span class="list-excerpt">/${esc(r.slug)}/</span></td><td class="hide-mobile">${esc(isPage?(r.blocks?.length?'Landing page':'Trang nội dung'):(r.category||'Chưa phân loại'))}</td><td><span class="status ${esc(r.status||'draft')}">${labelStatus(r.status)}</span></td><td class="hide-mobile">${date(r.updatedAt||r.publishedAt)}</td><td>${button('Sửa','edit-record',false,`data-collection="${collection}" data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${all.length?'Chưa có kết quả phù hợp':'Bắt đầu từ một câu chuyện'}</h3><p>${all.length?'Thử đổi từ khóa hoặc bộ lọc.':'Bạn có thể viết nội dung mới hoặc nhập nội dung từ website hiện tại trong mục Xuất bản & cấu hình.'}</p>${!all.length?button(isPage?'Tạo trang đầu tiên':'Viết bài đầu tiên','new-record',true,`data-collection="${collection}"`):''}</div>`}</div>`;
    $('#list-search').addEventListener('input',e=>{const start=e.target.selectionStart;state.query=e.target.value;renderList(collection);$('#list-search').focus();$('#list-search').setSelectionRange(start,start);});$('#list-status').addEventListener('change',e=>{state.filter=e.target.value;renderList(collection);});}
  function safeURL(value,allowData=false){const s=String(value||'').trim();if(allowData&&/^data:image\/(png|jpeg|gif|webp);base64,/i.test(s))return s;if(s.startsWith('/')&&!s.startsWith('//')||s.startsWith('./')||s.startsWith('../')||s.startsWith('#'))return s;try{const u=new URL(s,location.href);return ['http:','https:','mailto:','tel:'].includes(u.protocol)?s:'';}catch{return '';}}
  function cleanHTML(html){const doc=new DOMParser().parseFromString(String(html||''),'text/html');const allowed=new Set(['P','DIV','SPAN','H2','H3','H4','H5','H6','B','STRONG','I','EM','U','S','A','IMG','UL','OL','LI','BLOCKQUOTE','BR','HR','TABLE','THEAD','TBODY','TR','TD','TH','FIGURE','FIGCAPTION','CODE','PRE','SUP','SUB','DETAILS','SUMMARY']);const blocked=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','FORM','INPUT','BUTTON','TEXTAREA','SELECT','SVG','MATH','LINK','META','BASE']);const walk=el=>{[...el.children].forEach(n=>{if(blocked.has(n.tagName)){n.remove();return;}walk(n);if(!allowed.has(n.tagName)){n.replaceWith(...n.childNodes);return;}[...n.attributes].forEach(a=>{const ok=(n.tagName==='A'&&['href','title'].includes(a.name))||(n.tagName==='IMG'&&['src','alt','width','height'].includes(a.name))||['id','colspan','rowspan'].includes(a.name);if(!ok)n.removeAttribute(a.name);});if(n.hasAttribute('href'))n.setAttribute('href',safeURL(n.getAttribute('href')));if(n.tagName==='A')n.setAttribute('rel','noopener noreferrer');if(n.hasAttribute('src')){const src=safeURL(n.getAttribute('src'));if(!src){n.remove();return;}n.setAttribute('src',src);} });};walk(doc.body);return doc.body.innerHTML;}
  function defaultRecord(collection){return {type:collection==='pages'?'page':'post',title:'',slug:'',excerpt:'',content:'',cover:'',coverAlt:'',category:'',tags:[],author:state.user?.name||'Lazi Voyage',publishedAt:new Date().toISOString(),status:'draft',seo:{},aio:{summary:'',sources:[],faq:[],reviewedAt:''},blocks:[],hideHeader:false,hideFooter:false};}
  function editRecord(collection,id){if(state.dirty&&!confirm('Bỏ thay đổi chưa lưu để mở nội dung khác?'))return;state.collection=collection;state.record=id?clone((state.data[collection]||[]).find(r=>String(r.id)===String(id))):defaultRecord(collection);if(!state.record){notify('Không tìm thấy nội dung.',true);return;}state.dirty=false;state.blockIndex=0;renderEditor();}
  function pairsText(items,keyA='label',keyB='url'){return (items||[]).map(x=>typeof x==='string'?x:`${x[keyA]||''} | ${x[keyB]||''}`).join('\n');}
  function parsePairs(text,keyA='label',keyB='url'){return lines(text).map(s=>{const pos=s.indexOf('|');return {[keyA]:(pos<0?s:s.slice(0,pos)).trim(),[keyB]:(pos<0?'':s.slice(pos+1)).trim()};});}
  function renderEditor(){editorSelection=null;const r=state.record,isPage=state.collection==='pages',seo=r.seo||{},aio=r.aio||{};$('#main').innerHTML=pageHead(isPage?'Biên tập trang':'Biên tập bài viết',`Bản đang sửa được lưu riêng. Đích xuất bản: ${esc(settings().publishUrl)}`,`${button('← Danh sách','back-list')}${button('Xem trước','preview-record')}${button('Lưu nháp','save-record')}${state.user?.role==='admin'?button(isPage?'Xuất bản trang':'Xuất bản bài','publish-record',true):''}`)+`<div class="editor-layout"><div><div class="panel"><label class="title-label">Tiêu đề<input class="title-input" name="title" placeholder="Bắt đầu một câu chuyện…" value="${esc(r.title)}" maxlength="300"></label><div class="slug-label"><span>Đường dẫn /</span><input name="slug" aria-label="Slug đường dẫn" value="${esc(r.slug)}" placeholder="duong-dan-bai-viet"><button class="text-button" type="button" data-action="generate-slug">Tạo từ tiêu đề</button></div>${area('excerpt','Mô tả ngắn',r.excerpt,2)}<div class="editor-toolbar" role="toolbar" aria-label="Định dạng nội dung">${[['bold','B','In đậm'],['italic','I','In nghiêng'],['formatBlock','H2','Tiêu đề H2'],['formatBlock','H3','Tiêu đề H3'],['formatBlock','P','Đoạn văn'],['insertUnorderedList','• Danh sách','Danh sách'],['blockquote','❝','Trích dẫn'],['link','Liên kết','Chèn liên kết'],['image','Ảnh','Chèn ảnh'],['html','HTML','Sửa mã HTML']].map(([cmd,text,title])=>`<button type="button" data-command="${cmd}" data-value="${text}" aria-label="${title}">${text}</button>`).join('')}</div><div id="rich-editor" class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Nội dung bài viết" data-placeholder="Viết câu chuyện của bạn tại đây…">${cleanHTML(r.content)}</div><div class="editor-foot"><span id="word-count"></span><span id="save-state">${r.id?'Đã tải phiên bản '+(r.version||1):'Bản nháp mới'}</span></div></div>${isPage?`<div class="panel"><div class="split-heading"><h2>Các khối landing page</h2><span class="small muted">${r.blocks?.length||0} khối</span></div><p class="note">Các khối xuất hiện sau phần nội dung. Chọn khối để chỉnh; dùng mũi tên để đổi thứ tự.</p><div id="blocks-list"></div><div id="block-fields"></div><div class="field-inline"><label>Loại khối<select id="new-block-type">${[['hero','Ảnh bìa & tiêu đề'],['text','Nội dung văn bản'],['image','Hình ảnh'],['posts','Bài viết liên quan'],['faq','Câu hỏi thường gặp'],['cta','Nút liên hệ'],['contact','Thông tin liên hệ']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label>${button('+ Thêm khối','add-block')}</div></div>`:''}<div class="panel"><div class="tabs" role="tablist" aria-label="Tối ưu nội dung"><button type="button" class="tab" role="tab" aria-selected="true" data-editor-tab="seo">SEO</button><button type="button" class="tab" role="tab" aria-selected="false" data-editor-tab="aio">AIO & nguồn tham khảo</button><button type="button" class="tab" role="tab" aria-selected="false" data-editor-tab="checks">Kiểm tra nội dung</button></div><div data-editor-panel="seo">${field('seoTitle','Tiêu đề SEO',seo.title||r.title,'text','Để trống để dùng tiêu đề bài theo mẫu website.')}${area('seoDescription','Mô tả SEO',seo.description||r.excerpt,3)}${field('canonical','Canonical',seo.canonical||'','url','Để trống để CMS tạo từ domain chính và đường dẫn.')}${field('ogImage','Ảnh chia sẻ mạng xã hội',seo.ogImage||'')}${check('noindex','Không đưa trang này vào kết quả tìm kiếm',seo.noindex)}<div class="seo-preview"><div class="url" id="seo-preview-url"></div><div class="seo-title" id="seo-preview-title"></div><p id="seo-preview-description"></p></div></div><div data-editor-panel="aio" hidden>${area('aioSummary','Tóm tắt trả lời trực tiếp',aio.summary||'',3,'Tóm tắt ngắn, rõ thông tin chính và hữu ích cho người đọc.')}${area('aioSources','Nguồn tham khảo',pairsText(aio.sources,'title','url'),4,'Mỗi dòng: Tên nguồn | https://duong-dan-nguon')}${area('aioFaq','Câu hỏi thường gặp',pairsText(aio.faq,'question','answer'),5,'Mỗi dòng: Câu hỏi | Câu trả lời. Nội dung này sẽ hiển thị trên trang.')}${field('reviewedAt','Ngày kiểm chứng nội dung',(aio.reviewedAt||'').slice(0,10),'date')}<p class="note">Các trường này hỗ trợ nội dung rõ ràng, có nguồn và có người chịu trách nhiệm; không bảo đảm được công cụ AI trích dẫn.</p></div><div data-editor-panel="checks" hidden><ul id="editor-checks" class="checklist"></ul></div></div></div><aside class="editor-aside"><div class="panel"><h3>Thông tin ${isPage?'trang':'bài'}</h3><p><span class="status ${esc(r.status||'draft')}">${labelStatus(r.status)}</span></p>${field('author','Tác giả',r.author||'')}${field('publishedAt','Ngày đăng',localDateTime(r.publishedAt),'datetime-local')}${isPage?`${check('hideHeader','Ẩn header trên trang này',r.hideHeader)}${check('hideFooter','Ẩn footer trên trang này',r.hideFooter)}`:`<label>Chuyên mục<select name="category"><option value="">Chưa phân loại</option>${(state.data.categories||[]).map(c=>`<option value="${esc(c.name)}"${c.name===r.category||c.id===r.category?' selected':''}>${esc(c.name)}</option>`).join('')}${r.category&&!(state.data.categories||[]).some(c=>c.name===r.category||c.id===r.category)?`<option selected>${esc(r.category)}</option>`:''}</select></label>${field('tags','Tag',(r.tags||[]).join(', '),'text','Cách nhau bằng dấu phẩy.')}`}</div><div class="panel"><h3>Ảnh đại diện</h3>${r.cover?`<img id="cover-preview" src="${esc(safeURL(r.cover))}" alt="" style="width:100%;border-radius:6px;margin-bottom:10px">`:''}${field('cover','Đường dẫn ảnh',r.cover||'')}${button('Chọn từ thư viện','pick-cover')}${field('coverAlt','Mô tả ảnh (alt)',r.coverAlt||'')}</div><div class="panel"><h3>Phiên bản & thao tác</h3><p class="note">Lưu nháp không thay đổi nội dung đang hiển thị. Xuất bản sẽ áp dụng bản đang sửa.</p><div class="actions">${button('Lịch sử','record-history',false,r.id?'':'disabled')}${button('Nhân bản','duplicate-record')}</div>${r.id?`<div class="actions" style="margin-top:12px">${button('Đưa vào thùng rác','trash-record')}</div>`:''}</div></aside></div>`;updateEditorStats();if(isPage)drawBlocks();$('#rich-editor').addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html');document.execCommand('insertHTML',false,html?cleanHTML(html):esc(e.clipboardData.getData('text/plain')).replace(/\n/g,'<br>'));markDirty();updateEditorStats();});$('#rich-editor').addEventListener('input',updateEditorStats);}
  function markDirty(){state.dirty=true;const s=$('#save-state');if(s)s.textContent='Có thay đổi chưa lưu';}
  function collectRecord(){const r=clone(state.record);r.title=inputValue('title');r.slug=inputValue('slug')||(state.collection==='pages'&&state.record.id&&state.record.slug===''?'':slugify(r.title));r.excerpt=inputValue('excerpt');r.content=cleanHTML($('#rich-editor')?.innerHTML||'');r.cover=inputValue('cover');r.coverAlt=inputValue('coverAlt');r.author=inputValue('author');const d=inputValue('publishedAt');r.publishedAt=d?new Date(d).toISOString():r.publishedAt;r.status='draft';r.category=inputValue('category');r.tags=inputValue('tags').split(',').map(x=>x.trim()).filter(Boolean);r.seo={...r.seo,title:inputValue('seoTitle'),description:inputValue('seoDescription'),canonical:inputValue('canonical'),ogImage:inputValue('ogImage'),noindex:checked('noindex')};r.aio={...r.aio,summary:inputValue('aioSummary'),sources:parsePairs(inputValue('aioSources'),'title','url'),faq:parsePairs(inputValue('aioFaq'),'question','answer'),reviewedAt:inputValue('reviewedAt')};r.hideHeader=checked('hideHeader');r.hideFooter=checked('hideFooter');return r;}
  async function saveRecord(){const r=collectRecord();if(!r.title)throw new Error('Nhập tiêu đề trước khi lưu.');if(!r.slug&&state.collection!=='pages')throw new Error('Nhập đường dẫn cho bài viết.');const result=await api('save',{collection:state.collection,record:r});state.record=result.record;const arr=state.data[state.collection];const i=arr.findIndex(x=>String(x.id)===String(result.record.id));if(i<0)arr.unshift(result.record);else arr[i]=result.record;state.dirty=false;renderEditor();return result.record;}
  function contentChecks(r){const doc=new DOMParser().parseFromString(r.content||'','text/html');const imgs=[...doc.querySelectorAll('img')];return [[Boolean(r.title),'Có tiêu đề rõ ràng'],[Boolean(r.seo?.description||r.excerpt),'Có mô tả SEO hoặc mô tả ngắn'],[Boolean(doc.querySelector('h2')),'Nội dung có tiêu đề H2'],[imgs.every(i=>i.getAttribute('alt')?.trim())&&(!r.cover||Boolean(r.coverAlt)),'Ảnh có mô tả thay thế'],[Boolean(r.author),'Có tên tác giả'],[Boolean(r.aio?.summary),'Có tóm tắt trả lời trực tiếp'],[Boolean(r.aio?.sources?.some(s=>s.url)),'Có nguồn tham khảo'],[Boolean(r.aio?.reviewedAt),'Có ngày kiểm chứng nội dung']];}
  function checksHTML(r){return contentChecks(r).map(([ok,text])=>`<li><span class="check-mark${ok?'':' missing'}" aria-label="${ok?'Đã có':'Cần xem lại'}">${ok?'✓':'○'}</span>${text}</li>`).join('');}
  function updateEditorStats(){const el=$('#rich-editor');if(!el)return;const text=el.textContent.trim();$('#word-count').textContent=`${text?text.split(/\s+/).length:0} từ`;const r=collectRecord();$('#seo-preview-url').textContent=(settings().siteUrl||'')+'/'+r.slug+'/';$('#seo-preview-title').textContent=r.seo.title||r.title||'Tiêu đề trang';$('#seo-preview-description').textContent=r.seo.description||r.excerpt||'Mô tả nội dung trang sẽ hiển thị tại đây.';$('#editor-checks').innerHTML=checksHTML(r);}
  function drawBlocks(){const r=state.record;if(!r.blocks)r.blocks=[];const names={hero:'Ảnh bìa & tiêu đề',text:'Nội dung văn bản',image:'Hình ảnh',posts:'Bài viết liên quan',faq:'Câu hỏi thường gặp',cta:'Nút liên hệ',contact:'Thông tin liên hệ'};$('#blocks-list').innerHTML=r.blocks.map((b,i)=>`<div class="block-row"><button class="button${i===state.blockIndex?' primary':''}" data-action="select-block" data-index="${i}" type="button">${esc(names[b.type]||b.type)} · ${esc(b.title||'Chưa có tiêu đề')}</button>${button('↑','move-block',false,`data-index="${i}" data-dir="-1" aria-label="Đưa khối lên"${i===0?' disabled':''}`)}${button('↓','move-block',false,`data-index="${i}" data-dir="1" aria-label="Đưa khối xuống"${i===r.blocks.length-1?' disabled':''}`)}${button('×','remove-block',false,`data-index="${i}" aria-label="Xóa khối"`)}</div>`).join('');const b=r.blocks[state.blockIndex];$('#block-fields').innerHTML=b?`<div class="block-editor"><h4>${esc(names[b.type]||b.type)}</h4>${field('blockTitle','Tiêu đề khối',b.title||'')}${area('blockContent','Nội dung',b.content||'',3)}${['hero','image'].includes(b.type)?`${field('blockImage','Đường dẫn ảnh',b.image||'')}${field('blockImageAlt','Mô tả ảnh',b.imageAlt||'')}`:''}${['hero','cta','contact'].includes(b.type)?`${field('blockUrl',b.type==='contact'?'Email liên hệ (mailto:) hoặc liên kết':'Đường dẫn nút',b.url||'')}${field('blockButton','Nhãn nút',b.buttonText||'')}`:''}${b.type==='faq'?area('blockItems','Câu hỏi | Câu trả lời',pairsText(b.items,'question','answer'),5):''}${b.type==='posts'?field('blockTag','Lọc bài theo tag',b.tag||''):''}${check('blockHidden','Ẩn khối này',b.hidden)}</div>`:'';}
  function collectBlock(){const b=state.record?.blocks?.[state.blockIndex];if(!b||!$('#block-fields [name=blockTitle]'))return;b.title=inputValue('blockTitle');b.content=inputValue('blockContent');b.hidden=checked('blockHidden');if($('[name=blockImage]')){b.image=inputValue('blockImage');b.imageAlt=inputValue('blockImageAlt');}if($('[name=blockUrl]')){b.url=inputValue('blockUrl');b.buttonText=inputValue('blockButton');}if($('[name=blockItems]'))b.items=parsePairs(inputValue('blockItems'),'question','answer');if($('[name=blockTag]'))b.tag=inputValue('blockTag');}
  function renderTaxonomy(){const list=(collection,title)=>`<div class="panel"><div class="split-heading"><h2>${title}</h2>${button('+ Thêm','new-taxonomy',false,`data-collection="${collection}"`)}</div>${(state.data[collection]||[]).length?`<table><tbody>${state.data[collection].map(r=>`<tr><td><button class="title-button" type="button" data-action="edit-taxonomy" data-collection="${collection}" data-id="${esc(r.id)}">${esc(r.name)}</button><small class="muted" style="display:block">/${esc(r.slug)}/</small></td><td>${button('Sửa','edit-taxonomy',false,`data-collection="${collection}" data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table>`:'<p class="note">Chưa có dữ liệu. Tạo mới hoặc nhập từ website hiện tại.</p>'}</div>`;$('#main').innerHTML=pageHead('Chuyên mục & tag','Tổ chức các câu chuyện thành những chủ đề có thể tìm và khám phá.')+`<div class="two-col">${list('categories','Chuyên mục')}${list('tags','Tag')}</div>`;}
  function taxonomyModal(collection,id){const r=id?state.data[collection].find(x=>String(x.id)===String(id)):{};openModal(collection==='categories'?'Chỉnh sửa chuyên mục':'Chỉnh sửa tag',`<form data-form="taxonomy" data-collection="${collection}" data-id="${esc(r.id||'')}">${field('name','Tên',r.name||'')}${field('slug','Slug',r.slug||'')}${area('description','Mô tả',r.description||'',3)}${collection==='categories'?`<label>Chuyên mục cha<select name="parent"><option value="">Không có</option>${state.data.categories.filter(c=>c.id!==r.id).map(c=>`<option value="${esc(c.id)}"${c.id===r.parent?' selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:''}${field('cover','Ảnh đại diện phân loại',r.cover||'')}${field('seoTitle','Tiêu đề SEO',r.seo?.title||'')}${area('seoDescription','Mô tả SEO',r.seo?.description||'',3)}<div class="actions"><button class="button primary" type="submit">Lưu thay đổi</button>${r.id?button('Xóa','remove-taxonomy',false,`data-collection="${collection}" data-id="${esc(r.id)}"`):''}</div></form>`);}
  function renderMedia(picker=false){const list=state.data.media||[];const tiles=list.map(m=>`<button class="media-tile" type="button" data-action="${picker?'choose-media':'edit-media'}" data-id="${esc(m.id)}"><img src="${esc(safeURL(m.url||m.path))}" alt="${esc(m.alt||'')}" loading="lazy"><div>${esc(m.name||m.filename||'Ảnh')}<small>${esc(m.mime||'')} ${m.size?Math.round(m.size/1024)+' KB':''}</small></div></button>`).join('');const content=`<div class="notice">Ảnh PNG, JPEG, WebP hoặc GIF · Tối đa 8 MB. Không tải file thực thi hoặc SVG.</div><input type="file" id="media-file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><div class="media-grid">${tiles}</div>${!list.length?'<div class="empty"><h3>Thư viện đang trống</h3><p>Upload ảnh đầu tiên để dùng lại trong bài viết và landing page.</p></div>':''}`;if(picker){openModal('Chọn ảnh đại diện',`<div class="actions" style="margin-bottom:18px">${button('+ Tải ảnh lên','upload-media',true)}</div>`+content);}else $('#main').innerHTML=pageHead('Thư viện ảnh','Quản lý hình ảnh, chú thích và thông tin nguồn tại một nơi.',button('+ Tải ảnh lên','upload-media',true))+content;}
  function mediaModal(id){const r=state.data.media.find(m=>String(m.id)===String(id));if(!r)return;openModal('Thông tin ảnh',`<form data-form="media" data-id="${esc(r.id)}"><img src="${esc(safeURL(r.url||r.path))}" alt="" style="max-width:100%;max-height:280px;display:block;margin:auto auto 20px;border-radius:7px">${field('alt','Văn bản thay thế (alt)',r.alt||'')}${field('caption','Chú thích',r.caption||'')}${field('source','Nguồn ảnh',r.source||'')}${field('url','Đường dẫn',r.url||r.path||'')}<button class="button primary" type="submit">Lưu thông tin ảnh</button></form>`);}
  function renderAppearance(){const s=settings();$('#main').innerHTML=pageHead('Header & footer','Thiết lập các thành phần dùng chung trên toàn website.',button('Lưu cấu hình nháp','save-appearance',true))+`<div class="notice">Sau khi lưu, vào Xuất bản & cấu hình → Áp dụng cấu hình website để cập nhật website đang hiển thị.</div><div class="two-col"><div class="panel"><h2>Header</h2>${field('headerLogo','Đường dẫn logo',s.header.logo)}${area('headerMenu','Menu chính',pairsText(s.header.menu),7,'Mỗi dòng: Nhãn menu | /duong-dan/ · Ví dụ: Blog | /blog/')}${check('headerSticky','Header cố định khi cuộn',s.header.sticky)}${check('headerSearch','Hiển thị tìm kiếm',s.header.showSearch)}</div><div class="panel"><h2>Footer</h2>${area('footerDescription','Giới thiệu ngắn',s.footer.description,3)}${field('footerEmail','Email',s.footer.email,'email')}${field('footerCopyright','Dòng bản quyền',s.footer.copyright)}${area('footerLinks','Liên kết bổ sung',pairsText(s.footer.links),5,'Mỗi dòng: Nhãn liên kết | URL')}</div></div>`;}
  function renderSnippets(){const list=state.data.snippets||[];const names={head:'Trước </head>',body_start:'Sau <body>',body_end:'Trước </body>'};$('#main').innerHTML=pageHead('Mã chèn website','Quản lý các đoạn xác minh, đo lường và tích hợp. Code không được thực thi trong trang quản trị.',button('+ Thêm đoạn mã','new-snippet',true))+`<div class="notice warning">Đoạn mã được áp dụng khi xuất bản cấu hình. Chỉ bật các mã bạn tin cậy; các mã đo lường nên tắt khi test.</div><div class="list-surface">${list.length?`<table><thead><tr><th>Tên đoạn mã</th><th>Vị trí</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(names[r.position]||r.position)}</td><td><span class="status${r.enabled?' published':''}">${r.enabled?'Đang bật':'Đang tắt'}</span></td><td>${button('Chỉnh sửa','edit-snippet',false,`data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h3>Chưa có mã chèn</h3><p>Thêm từng đoạn mã với tên và phạm vi áp dụng riêng để dễ quản lý.</p></div>'}</div>`;}
  function snippetModal(id){const r=id?state.data.snippets.find(x=>String(x.id)===String(id)):{};openModal('Cấu hình đoạn mã',`<form data-form="snippet" data-id="${esc(r.id||'')}">${field('name','Tên đoạn mã',r.name||'')}<div class="form-grid"><label>Vị trí<select name="position">${[['head','Trước </head>'],['body_start','Ngay sau <body>'],['body_end','Trước </body>']].map(([v,l])=>`<option value="${v}"${r.position===v?' selected':''}>${esc(l)}</option>`).join('')}</select></label><label>Phạm vi<select name="scope">${[['all','Toàn bộ website công khai'],['posts','Chỉ bài viết'],['pages','Chỉ trang & landing page'],['urls','Các URL được chọn']].map(([v,l])=>`<option value="${v}"${r.scope===v?' selected':''}>${l}</option>`).join('')}</select></label></div>${area('urls','URL áp dụng (khi chọn Các URL)',(r.urls||[]).join('\n'),3,'Mỗi dòng một đường dẫn, ví dụ /contact/.')}<label>Nội dung mã<textarea class="code-editor" name="code" spellcheck="false" rows="10">${esc(r.code||'')}</textarea></label>${check('enabled','Bật đoạn mã',r.enabled)}${check('allowTest','Cho phép chạy đoạn mã trên môi trường test',r.allowTest)}${field('order','Thứ tự chạy (số nhỏ chạy trước)',r.order||0,'number')}<div class="actions"><button class="button primary" type="submit">Lưu cấu hình nháp</button>${r.id?button('Xóa đoạn mã','remove-snippet',false,`data-id="${esc(r.id)}"`):''}</div></form>`);}
  function renderSEO(){const s=settings();const all=[...(state.data.posts||[]),...(state.data.pages||[])];const incomplete=all.filter(r=>contentChecks(r).some(([ok])=>!ok));$('#main').innerHTML=pageHead('SEO & AIO','Tối ưu khả năng tìm thấy nội dung: thông tin rõ ràng, cấu trúc tốt và nguồn đáng tin cậy.',state.user?.role==='admin'?button('Lưu cấu hình SEO','save-seo',true):'')+`<div class="notice">SEO là nền tảng cho các tính năng tìm kiếm AI. Không có điểm số nội bộ hoặc cấu hình đặc biệt nào bảo đảm được AI trích dẫn. <a href="https://developers.google.com/search/docs/appearance/ai-features" target="_blank" rel="noopener">Hướng dẫn Google Search Central ↗</a></div><div class="two-col"><div><div class="panel"><h2>Thông tin tìm kiếm</h2>${field('titleTemplate','Mẫu tiêu đề',s.seo.titleTemplate,'text','Dùng %title% để chèn tiêu đề trang.')}${area('siteDescription','Mô tả website',s.seo.description,3)}${field('organizationName','Tên tổ chức',s.seo.organizationName)}${area('sameAs','Trang hồ sơ chính thức',(s.seo.sameAs||[]).join('\n'),3,'Mỗi dòng một URL mạng xã hội/hồ sơ chính thức.')}${field('googleVerification','Mã xác minh Google Search Console',s.seo.googleVerification||'','text','Chỉ nhập giá trị content của thẻ meta google-site-verification.')}${field('bingVerification','Mã xác minh Bing Webmaster',s.seo.bingVerification||'')}</div><div class="panel"><h2>Thông tin giúp hiểu nội dung</h2>${area('aioAbout','Giới thiệu về Lazi',s.aio.about,4)}${area('editorialPolicy','Chính sách biên tập & kiểm chứng',s.aio.editorialPolicy,4)}<p class="note">Tác giả, tóm tắt, nguồn tham khảo, FAQ và ngày kiểm chứng được quản lý riêng trong mỗi bài/trang.</p></div></div><div><div class="panel"><h2>Kiểm tra nội dung</h2><p class="note">${incomplete.length} / ${all.length} nội dung có mục cần xem lại. Đây là danh sách kiểm tra biên tập, không phải dự báo thứ hạng.</p>${incomplete.length?`<ul class="checklist">${incomplete.slice(0,15).map(r=>`<li><span class="check-mark missing">○</span><button type="button" class="title-button" data-action="edit-record" data-collection="${state.data.posts.some(p=>p.id===r.id)?'posts':'pages'}" data-id="${esc(r.id)}">${esc(r.title)}</button></li>`).join('')}</ul>`:'<p class="note">Chưa có nội dung cần kiểm tra, hoặc chưa nhập dữ liệu.</p>'}</div><div class="panel"><h2>Chuyển hướng URL</h2>${area('redirects','Danh sách chuyển hướng',(s.redirects||[]).map(r=>`${r.from} | ${r.to} | ${r.code||301}`).join('\n'),8,'Mỗi dòng: /duong-dan-cu/ | /duong-dan-moi/ | 301. Chỉ dùng đường dẫn trong website.')}</div><div class="panel"><h2>Thu thập & lập chỉ mục</h2><ul class="checklist"><li><span class="check-mark">✓</span>CMS có noindex, không đưa vào sitemap.</li><li><span class="check-mark">✓</span>Sitemap, RSS và tìm kiếm cập nhật khi xuất bản.</li><li><span class="check-mark">○</span>Canonical theo domain chính; môi trường test cần noindex.</li><li><span class="check-mark">○</span>Kiểm tra Search Console sau khi phát hành domain chính.</li></ul><p class="note" style="margin-top:15px">Schema được tạo từ nội dung thực hiển thị. llms.txt không phải điều kiện bắt buộc của Google AI Search.</p></div></div></div>`;if(state.user?.role!=='admin')$$('input,textarea,select').forEach(el=>el.disabled=true);}
  function renderUsers(){if(state.user?.role!=='admin'){notify('Chức năng này dành cho quản trị viên.',true);return navigate('posts',true);}$('#main').innerHTML=pageHead('Tài khoản quản trị','Cấp quyền cho người cộng tác. Website không có đăng ký tài khoản công khai.',button('+ Tạo tài khoản','new-user',true))+`<div class="notice">Quản trị viên quản lý toàn bộ website và tài khoản. Biên tập viên quản lý nội dung; không có quyền sửa mã chèn hoặc cấp quyền.</div><div class="list-surface" id="users-list"><div class="empty">Đang tải tài khoản…</div></div>`;if(state.preview){$('#users-list').innerHTML='<div class="empty"><h3>Tạo tài khoản cần backend</h3><p>Đăng nhập bằng tài khoản quản trị sau khi cài CMS trên Vietnix để tạo thêm tài khoản.</p></div>';return;}api('users').then(data=>{state.users=data.users||[];if(state.section!=='users')return;$('#users-list').innerHTML=`<table><thead><tr><th>Tài khoản</th><th>Vai trò</th><th>Trạng thái</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td>${esc(u.name)}<small class="muted" style="display:block">${esc(u.email)}</small></td><td>${u.role==='admin'?'Quản trị viên':'Biên tập viên'}</td><td><span class="status${u.active?' published':''}">${u.active?'Hoạt động':'Đã khóa'}</span></td><td>${button('Chỉnh sửa','edit-user',false,`data-id="${esc(u.id)}"`)}</td></tr>`).join('')}</tbody></table>`;}).catch(e=>notify(e.message,true));}
  function userModal(id){const r=id?state.users.find(u=>String(u.id)===String(id)):{};openModal(r.id?'Chỉnh sửa tài khoản':'Tạo tài khoản quản trị',`<form data-form="user" data-id="${esc(r.id||'')}">${field('name','Họ tên',r.name||'')}${field('email','Email',r.email||'','email')}${field('password',r.id?'Mật khẩu mới (để trống để giữ nguyên)':'Mật khẩu ban đầu','','password','Tối thiểu 12 ký tự.')}<label>Vai trò<select name="role"><option value="editor"${r.role==='editor'?' selected':''}>Biên tập viên</option><option value="admin"${r.role==='admin'?' selected':''}>Quản trị viên</option></select></label>${check('active','Tài khoản hoạt động',r.active!==false)}<p class="note">Không thể khóa hoặc hạ quyền quản trị viên hoạt động cuối cùng.</p><button class="button primary" type="submit">${r.id?'Lưu tài khoản':'Tạo tài khoản'}</button></form>`);}
  function renderSettings(){const s=settings();$('#main').innerHTML=pageHead('Xuất bản & cấu hình','Quản lý môi trường, nguồn nội dung và các lần cập nhật website.')+`<div class="two-col"><div><div class="panel"><h2>Thông tin website</h2>${field('siteName','Tên website',s.siteName)}${field('siteUrl','Domain chính / canonical',s.siteUrl,'url')}${field('publishUrl','Đích xuất bản hiện tại',s.publishUrl,'url')}<label>Môi trường<select name="environment"><option value="test"${s.environment==='test'?' selected':''}>Test — noindex</option><option value="production"${s.environment==='production'?' selected':''}>Production — website chính</option></select></label>${button('Lưu cấu hình nháp','save-settings',true)}</div><div class="panel"><h2>Nguồn nội dung hiện có</h2><p class="note">Nhập các bài và trang được hỗ trợ từ HTML hiện tại vào kho dữ liệu CMS. Bước này không ghi đè trang công khai. Công cụ Sử Việt và các tài nguyên hiện có được giữ nguyên.</p><div class="actions">${button('Nhập từ website hiện tại','import')}${button('Xuất dữ liệu JSON','export')}</div><p class="help">File JSON gồm nội dung và cấu hình, không bao gồm mật khẩu hoặc dữ liệu phiên đăng nhập.</p></div></div><div><div class="panel"><h2>Áp dụng cấu hình website</h2><div class="notice">Đích: <strong>${esc(s.publishUrl)}</strong></div><p class="note">Áp dụng header, footer, SEO và mã chèn đã lưu vào các trang đang xuất bản; đồng thời cập nhật sitemap, RSS và dữ liệu tìm kiếm.</p><p class="note"><strong>Thao tác này không xuất bản các bài/trang nháp.</strong> Mở từng bài hoặc trang để xuất bản nội dung đang sửa.</p>${button('Áp dụng cấu hình website','publish-settings',true)}</div><div class="panel"><h2>Lịch sử & bảo toàn dữ liệu</h2><p class="note">Lịch sử nội dung được lưu trong CMS. Mở bài/trang → Lịch sử để xem và khôi phục bản nháp.</p><p class="note">Dữ liệu và tài khoản được lưu ngoài thư mục website. Khi upload code mới, dùng quy trình triển khai có bảo vệ các file CMS đã xuất bản.</p>${button('Đổi mật khẩu của tôi','change-password')}</div></div></div>`;}
  async function saveSettings(kind){const s=settings();if(kind==='appearance'){s.header={...s.header,logo:inputValue('headerLogo'),menu:parsePairs(inputValue('headerMenu')),sticky:checked('headerSticky'),showSearch:checked('headerSearch')};s.footer={...s.footer,description:inputValue('footerDescription'),email:inputValue('footerEmail'),copyright:inputValue('footerCopyright'),links:parsePairs(inputValue('footerLinks'))};}if(kind==='seo'){s.seo={...s.seo,titleTemplate:inputValue('titleTemplate'),description:inputValue('siteDescription'),organizationName:inputValue('organizationName'),sameAs:lines(inputValue('sameAs')),googleVerification:inputValue('googleVerification'),bingVerification:inputValue('bingVerification')};s.aio={...s.aio,about:inputValue('aioAbout'),editorialPolicy:inputValue('editorialPolicy')};s.redirects=lines(inputValue('redirects')).map(line=>{const [from,to,code]=line.split('|').map(s=>s.trim());if(!from?.startsWith('/')||from.startsWith('//')||!to?.startsWith('/')||to.startsWith('//')||!['301','302'].includes(code||'301'))throw new Error('Chuyển hướng cần dạng /cu/ | /moi/ | 301 hoặc 302.');return {from,to,code:Number(code||301)};});}if(kind==='settings'){s.siteName=inputValue('siteName');s.siteUrl=inputValue('siteUrl');s.publishUrl=inputValue('publishUrl');s.environment=inputValue('environment');}const result=await api('save',{collection:'settings',record:s});state.data.settings=result.record;state.dirty=false;drawChrome();notify('Đã lưu cấu hình nháp. Áp dụng cấu hình website để đưa thay đổi ra trang công khai.');}
  async function previewRecord(){collectBlock();const r=collectRecord();let html;if(state.record.id&&!state.dirty&&!state.preview){const url=new URL(API,location.href);url.searchParams.set('action','preview');url.searchParams.set('collection',state.collection);url.searchParams.set('id',state.record.id);const response=await fetch(url,{credentials:'same-origin'});html=await response.text();if(!response.ok){let msg='Không thể xem trước.';try{msg=JSON.parse(html).error||msg;}catch{}throw new Error(msg);}}else{html=`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src https: http: data:; style-src 'unsafe-inline'"><style>body{font:17px/1.85 Georgia,serif;color:#263d39;max-width:760px;padding:30px;margin:auto}h1{font-size:36px;line-height:1.25}img{max-width:100%;height:auto}small{color:#657a70}blockquote{border-left:3px solid #729d86;padding-left:20px}a{color:#086d67}</style></head><body><small>BẢN XEM TRƯỚC NỘI DUNG CHƯA LƯU</small><h1>${esc(r.title)}</h1><p>${esc(r.excerpt)}</p>${r.cover?`<img src="${esc(new URL(safeURL(r.cover),location.origin).href)}" alt="${esc(r.coverAlt)}">`:''}${cleanHTML(r.content)}${(r.blocks||[]).map(b=>`<section><h2>${esc(b.title)}</h2><p>${esc(b.content)}</p>${b.image?`<img src="${esc(new URL(safeURL(b.image),location.origin).href)}" alt="${esc(b.imageAlt)}">`:''}</section>`).join('')}</body></html>`;}
    openModal('Xem trước · Mã chèn bị vô hiệu hóa','<iframe class="preview-frame" id="content-preview" sandbox="" title="Xem trước nội dung"></iframe>');$('#content-preview').srcdoc=html;}
  async function recordHistory(){const data=await api('revisions',undefined,{collection:state.collection,id:state.record.id});const revisions=data.revisions||[];openModal('Lịch sử phiên bản',revisions.length?revisions.map(r=>`<div class="revision-row"><div><strong>Phiên bản ${esc(r.version||r.id)}</strong><small>${esc(r.createdAt||r.created_at||'')} ${esc(r.actorName||r.action||'')}</small></div>${state.user?.role==='admin'?button('Khôi phục nháp','restore-revision',false,`data-revision-id="${esc(r.id)}"`):''}</div>`).join(''):'<p class="muted">Chưa có lịch sử phiên bản.</p>');}
  function passwordModal(){openModal('Đổi mật khẩu',`<form data-form="password">${field('currentPassword','Mật khẩu hiện tại','','password')}${field('newPassword','Mật khẩu mới','','password','Tối thiểu 12 ký tự.')}<button class="button primary" type="submit">Cập nhật mật khẩu</button></form>`);}
  function insertAtCaret(html){$('#rich-editor').focus();document.execCommand('insertHTML',false,html);markDirty();updateEditorStats();}
  let editorSelection=null;
  document.addEventListener('selectionchange',()=>{const selection=window.getSelection();if(selection.rangeCount&&$('#rich-editor')?.contains(selection.anchorNode))editorSelection=selection.getRangeAt(0).cloneRange();});
  function restoreSelection(){const selection=window.getSelection();if(editorSelection){selection.removeAllRanges();selection.addRange(editorSelection);}$('#rich-editor')?.focus();}
  function editorCommand(cmd,value){restoreSelection();if(['bold','italic','insertUnorderedList'].includes(cmd)){document.execCommand(cmd,false);markDirty();return;}if(cmd==='formatBlock'){document.execCommand('formatBlock',false,value.toLowerCase());markDirty();return;}if(cmd==='blockquote'){document.execCommand('formatBlock',false,'blockquote');markDirty();return;}if(cmd==='link')openModal('Chèn liên kết',`<form data-form="insert-link">${field('url','Địa chỉ liên kết','','url')}${field('text','Nội dung hiển thị (để trống để dùng phần đang chọn)')}<button class="button primary" type="submit">Chèn liên kết</button></form>`);if(cmd==='image')openModal('Chèn ảnh vào bài',`<form data-form="insert-image">${field('url','Đường dẫn ảnh')}${field('alt','Mô tả ảnh (alt)')}<button class="button primary" type="submit">Chèn ảnh</button></form>`);if(cmd==='html')openModal('Biên tập HTML nội dung',`<form data-form="html"><p class="note">Chỉ hỗ trợ HTML nội dung. Script, iframe, form và thuộc tính sự kiện sẽ bị loại bỏ.</p><label>HTML<textarea class="code-editor" name="html" rows="16" spellcheck="false">${esc($('#rich-editor').innerHTML)}</textarea></label><button class="button primary" type="submit">Áp dụng vào bản đang sửa</button></form>`);}
  document.addEventListener('click',e=>{const section=e.target.closest('[data-section]');if(section){navigate(section.dataset.section);return;}const command=e.target.closest('[data-command]');if(command){editorCommand(command.dataset.command,command.dataset.value);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
    run(el,async()=>{
      if(a==='new-record')editRecord(el.dataset.collection);
      if(a==='edit-record')editRecord(el.dataset.collection,el.dataset.id);
      if(a==='back-list'){navigate(state.collection==='pages'?'pages':'posts');}
      if(a==='generate-slug'){$('[name=slug]').value=slugify(inputValue('title'));markDirty();updateEditorStats();}
      if(a==='save-record'){collectBlock();await saveRecord();notify('Đã lưu bản nháp. Nội dung công khai chưa thay đổi.');}
      if(a==='publish-record'){if(state.user?.role!=='admin')throw new Error('Chỉ quản trị viên được xuất bản nội dung.');collectBlock();const r=await saveRecord();const result=await api('publish',{collection:state.collection,id:r.id});state.dirty=false;const col=state.collection,id=r.id;const data=await api('bootstrap');state.data={...state.data,...data};editRecord(col,id);notify(result.message||'Đã xuất bản nội dung vào website được cấu hình.');}
      if(a==='preview-record')await previewRecord();
      if(a==='record-history'){if(state.preview)throw new Error('Lịch sử phiên bản cần kết nối backend.');await recordHistory();}
      if(a==='restore-revision'){if(!confirm('Khôi phục phiên bản này vào bản nháp? Nội dung đang xuất bản không thay đổi.'))return;const result=await api('restore',{revisionId:el.dataset.revisionId});if(result.record){state.record=result.record;const arr=state.data[state.collection];const i=arr.findIndex(r=>r.id===result.record.id);if(i>=0)arr[i]=result.record;closeModal();state.dirty=false;renderEditor();notify('Đã khôi phục vào bản nháp.');}else{closeModal();await load();notify('Đã khôi phục bản nháp.');}}
      if(a==='duplicate-record'){collectBlock();const r=collectRecord();['id','version','sourcePath','originalHtml','originalPath','createdAt','updatedAt','publishedSnapshot'].forEach(k=>delete r[k]);r.title+=' (bản sao)';r.slug=(r.slug||slugify(r.title))+'-ban-sao';r.status='draft';state.record=r;state.dirty=true;renderEditor();notify('Đã tạo bản sao đang biên tập. Lưu nháp để ghi vào CMS.');}
      if(a==='trash-record'){if(!confirm('Đưa nội dung vào thùng rác? Nếu đang xuất bản, trang công khai sẽ chỉ được cập nhật khi bạn áp dụng xuất bản theo hướng dẫn CMS.'))return;await api('remove',{collection:state.collection,id:state.record.id,version:state.record.version});state.dirty=false;const section=state.collection;await load();navigate(section,true);notify('Đã chuyển nội dung vào thùng rác.');}
      if(a==='new-taxonomy')taxonomyModal(el.dataset.collection);
      if(a==='edit-taxonomy')taxonomyModal(el.dataset.collection,el.dataset.id);
      if(a==='remove-taxonomy'){const r=state.data[el.dataset.collection].find(x=>String(x.id)===el.dataset.id);if(!confirm('Xóa mục phân loại này?'))return;await api('remove',{collection:el.dataset.collection,id:r.id,version:r.version});closeModal();await load();}
      if(a==='upload-media'){if(state.preview)throw new Error('Tải ảnh cần kết nối backend trên Vietnix.');const file=$('#media-file');file.onchange=async()=>{const selected=file.files[0];if(!selected)return;if(selected.size>8*1024*1024)return notify('Ảnh vượt quá 8 MB.',true);await run(el,async()=>{const form=new FormData();form.append('file',selected);const result=await api('upload',form);const media=result.record||result.media;if(media)state.data.media.unshift(media);else{const data=await api('bootstrap');state.data.media=data.media||[];}const picking=$('#modal').open;renderMedia(picking);notify('Đã tải ảnh lên thư viện.');});};file.click();}
      if(a==='edit-media')mediaModal(el.dataset.id);
      if(a==='pick-cover'){collectBlock();state.record=collectRecord();renderMedia(true);}
      if(a==='choose-media'){const r=state.data.media.find(m=>String(m.id)===el.dataset.id);$('[name=cover]').value=r.url||r.path||'';$('[name=coverAlt]').value=r.alt||'';closeModal();markDirty();updateEditorStats();}
      if(a==='save-appearance')await saveSettings('appearance');
      if(a==='new-snippet')snippetModal();
      if(a==='edit-snippet')snippetModal(el.dataset.id);
      if(a==='remove-snippet'){const r=state.data.snippets.find(s=>String(s.id)===el.dataset.id);if(!confirm('Xóa đoạn mã này?'))return;await api('remove',{collection:'snippets',id:r.id,version:r.version});closeModal();await load();notify('Đã xóa đoạn mã. Áp dụng cấu hình website để cập nhật trang công khai.');}
      if(a==='save-seo')await saveSettings('seo');
      if(a==='new-user')userModal();
      if(a==='edit-user')userModal(el.dataset.id);
      if(a==='save-settings')await saveSettings('settings');
      if(a==='publish-settings'){if(state.dirty)throw new Error('Lưu cấu hình trước khi áp dụng lên website.');const result=await api('publish',{});notify(result.message||'Đã áp dụng cấu hình vào các trang đang xuất bản.');}
      if(a==='import'){if(!confirm('Nhập nội dung từ website hiện tại? CMS sẽ tạo dữ liệu quản lý; trang công khai không được ghi đè ở bước này.'))return;const result=await api('import',{});await load();notify(result.message||'Đã nhập nội dung hiện tại vào CMS.');}
      if(a==='export'){const data={exportedAt:new Date().toISOString(),format:'lazivoyage-cms-content-v1',posts:state.data.posts,pages:state.data.pages,categories:state.data.categories,tags:state.data.tags,media:state.data.media,snippets:state.data.snippets,settings:state.data.settings};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='lazivoyage-content-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
      if(a==='change-password')passwordModal();
      if(a==='add-block'){collectBlock();state.record.blocks ||= [];state.record.blocks.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),type:$('#new-block-type').value,title:'',content:'',items:[]});state.blockIndex=state.record.blocks.length-1;drawBlocks();markDirty();}
      if(a==='select-block'){collectBlock();state.blockIndex=Number(el.dataset.index);drawBlocks();}
      if(a==='move-block'){collectBlock();const i=Number(el.dataset.index),j=i+Number(el.dataset.dir);if(j<0||j>=state.record.blocks.length)return;[state.record.blocks[i],state.record.blocks[j]]=[state.record.blocks[j],state.record.blocks[i]];state.blockIndex=j;drawBlocks();markDirty();}
      if(a==='remove-block'){collectBlock();state.record.blocks.splice(Number(el.dataset.index),1);state.blockIndex=Math.max(0,Math.min(state.blockIndex,state.record.blocks.length-1));drawBlocks();markDirty();}
    });
  });
  document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const kind=form.dataset.form;run($('button[type=submit]',form),async()=>{
    if(kind==='taxonomy'){const collection=form.dataset.collection;const old=state.data[collection].find(r=>String(r.id)===form.dataset.id)||{};const name=inputValue('name',form);if(!name)throw new Error('Nhập tên chuyên mục hoặc tag.');const record={...old,name,slug:inputValue('slug',form)||slugify(name),description:inputValue('description',form),parent:inputValue('parent',form),cover:inputValue('cover',form),seo:{...old.seo,title:inputValue('seoTitle',form),description:inputValue('seoDescription',form)}};await api('save',{collection,record});closeModal();await load();notify('Đã lưu phân loại nội dung.');}
    if(kind==='media'){const old=state.data.media.find(r=>String(r.id)===form.dataset.id);const record={...old,alt:inputValue('alt',form),caption:inputValue('caption',form),source:inputValue('source',form)};await api('save',{collection:'media',record});closeModal();await load();notify('Đã lưu thông tin ảnh.');}
    if(kind==='snippet'){const old=state.data.snippets.find(r=>String(r.id)===form.dataset.id)||{};const record={...old,name:inputValue('name',form),position:inputValue('position',form),scope:inputValue('scope',form),urls:lines(inputValue('urls',form)),code:inputValue('code',form),enabled:checked('enabled',form),allowTest:checked('allowTest',form),order:Number(inputValue('order',form)||0)};if(!record.name)throw new Error('Nhập tên đoạn mã.');await api('save',{collection:'snippets',record});closeModal();await load();notify('Đã lưu đoạn mã nháp. Chưa áp dụng lên trang công khai.');}
    if(kind==='user'){const old=state.users.find(u=>String(u.id)===form.dataset.id)||{};const record={...old,name:inputValue('name',form),email:inputValue('email',form),role:inputValue('role',form),active:checked('active',form)};const pwd=inputValue('password',form);if(pwd)record.password=pwd;if(!record.name||!record.email)throw new Error('Nhập họ tên và email.');if(!old.id&&!pwd)throw new Error('Nhập mật khẩu ban đầu.');if(pwd&&pwd.length<12)throw new Error('Mật khẩu tối thiểu 12 ký tự.');const saved=await api('user-save',{record});closeModal();if(String(saved.user?.id)===String(state.user?.id)){state.user=saved.user;if(!state.user.active){state.user=null;state.dirty=false;authScreen(false,'Tài khoản này đã bị khóa.');}else if(state.user.role!=='admin'){navigate('posts',true);}else{drawChrome();renderUsers();}}else renderUsers();notify(old.id?'Đã cập nhật tài khoản.':'Đã tạo tài khoản.');}
    if(kind==='password'){const currentPassword=inputValue('currentPassword',form),newPassword=inputValue('newPassword',form);if(newPassword.length<12)throw new Error('Mật khẩu mới tối thiểu 12 ký tự.');await api('password',{currentPassword,newPassword});closeModal();notify('Đã đổi mật khẩu.');}
    if(kind==='html'){const html=cleanHTML(inputValue('html',form));$('#rich-editor').innerHTML=html;closeModal();markDirty();updateEditorStats();}
    if(kind==='insert-link'){const url=safeURL(inputValue('url',form));if(!url)throw new Error('Liên kết không hợp lệ.');const text=inputValue('text',form);closeModal();restoreSelection();if(text)insertAtCaret(`<a href="${esc(url)}" rel="noopener noreferrer">${esc(text)}</a>`);else{document.execCommand('createLink',false,url);markDirty();}}
    if(kind==='insert-image'){const url=safeURL(inputValue('url',form));if(!url)throw new Error('Đường dẫn ảnh không hợp lệ.');const alt=inputValue('alt',form);closeModal();restoreSelection();insertAtCaret(`<figure><img src="${esc(url)}" alt="${esc(alt)}"></figure><p><br></p>`);}
  });});
  document.addEventListener('input',e=>{if(!$('#app').hidden&&e.target.closest('#main')&&!['list-search','list-status'].includes(e.target.id)){markDirty();if(state.record){if(e.target.closest('#block-fields'))collectBlock();updateEditorStats();}}});
  document.addEventListener('change',e=>{if(!$('#app').hidden&&e.target.closest('#main')&&!['list-search','list-status','media-file'].includes(e.target.id)){markDirty();if(state.record)updateEditorStats();}});
  document.addEventListener('click',e=>{const tab=e.target.closest('[data-editor-tab]');if(!tab)return;$$('[data-editor-tab]').forEach(t=>t.setAttribute('aria-selected',t===tab?'true':'false'));$$('[data-editor-panel]').forEach(p=>p.hidden=p.dataset.editorPanel!==tab.dataset.editorTab);if(tab.dataset.editorTab==='checks')updateEditorStats();});
  $('#modal-close').addEventListener('click',closeModal);
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  $('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open));});
  $('#account-button').addEventListener('click',()=>{if(state.preview)return notify('Kết nối backend PHP để quản lý tài khoản.');passwordModal();});
  $('#logout').addEventListener('click',()=>{if(state.preview){state.preview=false;state.user=null;location.href='./';return;}run($('#logout'),async()=>{await api('logout',{});state.user=null;state.dirty=false;authScreen();});});
  window.addEventListener('beforeunload',e=>{if(state.dirty&&!state.preview){e.preventDefault();e.returnValue='';}});
  async function boot(){if(new URLSearchParams(location.search).get('preview')==='1'){startPreview();return;}try{const session=await api('session');state.csrf=session.csrf||'';state.user=session.user;if(state.user)await load();else{authScreen(Boolean(session.needsSetup));if(session.needsSetup&&!session.setupReady){$('#auth-content').insertAdjacentHTML('afterbegin','<div class="notice warning">Tạo tài khoản đầu tiên cần mã thiết lập được sinh trong Terminal Vietnix. Xem hướng dẫn cài đặt CMS để lấy mã này.</div>');}}}catch(e){authScreen(false,e.message,true);}}
  boot();
})();
